settings.value:
# file generated by setuptools_scm
# don't change, don't track in version control
__version__ = version = {version!r}
__version_tuple__ = version_tuple = {version_tuple!r}

run.command:
export BASE_IMAGE=$( grep BASE_IMAGE= Dockerfile | cut -d= -f2 )
export BASE_IMAGE_NAME=${BASE_IMAGE%:*}
export BASE_TAG=${BASE_IMAGE#*:}
echo "BASE_IMAGE=$BASE_IMAGE" >> $BASH_ENV
echo "BASE_IMAGE_NAME=$BASE_IMAGE_NAME" >> $BASH_ENV
echo "BASE_TAG=$BASE_TAG" >> $BASH_ENV
env

sudo chown $(id -un):$(id -gn) -R /tmp/${DATASET}
sudo rm -rf /tmp/${DATASET}/work
sudo rm -rf /tmp/${DATASET}/work_partial

sudo chown $(id -un):$(id -gn) -R /tmp/${DATASET}
find /tmp/${DATASET}/work \( -name "*.nii.gz" -or -name "*.nii" -or -name "*.gii" -or -name "*.h5" \) \
    -exec sh -c 'rm -f {}; touch {}' \;
find /tmp/${DATASET}/work_partial \( -name "*.nii.gz" -or -name "*.nii" -or -name "*.gii" -or -name "*.h5" \) \
    -exec sh -c 'rm -f {}; touch {}' \;

sudo chown $(id -un):$(id -gn) -R /tmp/${DATASET}
find /tmp/${DATASET}/work \( -name "*.nii.gz" -or -name "*.nii" -or -name "*.gii" -or -name "*.h5" \) \
    -exec sh -c 'rm -f {}; touch {}' \;

sudo chown $(id -un):$(id -gn) -R /tmp/${DATASET}
find /tmp/${DATASET}/work \( -name "*.nii.gz" -or -name "*.nii" -or -name "*.gii" -or -name "*.h5" \) \
    -exec sh -c 'rm -f {}; touch {}' \;

# Format: docker/[<version-like>+]<tag> -> nipreps/fmriprep:<tag>
# <version-like>+<tag> guides setuptools_scm to get the right major/minor
docker tag nipreps/fmriprep nipreps/fmriprep:${CIRCLE_BRANCH##*[/+]}
docker push nipreps/fmriprep:${CIRCLE_BRANCH##*[/+]}

with.script:
const { data } = await github.rest.pulls.get({
  owner: process.env.OWNER,
  repo: process.env.REPO.split('/')[1],
  pull_number: process.env.PULL,
});
core.setOutput('remote', data.head.repo.html_url)
core.setOutput('branch', data.head.ref)

with.cache-from:
type=registry,ref=${{ env.REGISTRY }}/${{ env.IMAGE_NAME }}:gha-docker
type=registry,ref=${{ env.REGISTRY }}/${{ env.IMAGE_NAME }}:${{ env.TARGET_BRANCH }}
type=registry,ref=${{ env.REGISTRY }}/${{ env.IMAGE_NAME }}:${{ steps.meta.outputs.tags[0] }}
